start=s.index("function qaCpfDigits")
end=s.index("const P18_COMPARE=",start)
gen=r'''function qaCpfDigits(base){let a=base.split('').map(Number),sum=a.reduce((n,x,i)=>n+x*(10-i),0),d1=(sum*10)%11;if(d1===10)d1=0;a.push(d1);sum=a.reduce((n,x,i)=>n+x*(11-i),0);let d2=(sum*10)%11;if(d2===10)d2=0;return base+String(d1)+String(d2)}
function qaCnpjDv(base){const val=c=>/[0-9]/.test(c)?+c:c.charCodeAt(0)-48;const calc=(str,w)=>{let sum=[...str].reduce((n,c,i)=>n+val(c)*w[i],0),r=sum%11;return r<2?0:11-r};let d1=calc(base,[5,4,3,2,9,8,7,6,5,4,3,2]);let d2=calc(base+d1,[6,5,4,3,2,9,8,7,6,5,4,3,2]);return base+d1+d2}
function qaRndDigits(n){return Array.from({length:n},()=>Math.floor(Math.random()*10)).join('')}
function qaRndAlphaNum(n){const c='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';return Array.from({length:n},()=>c[Math.floor(Math.random()*c.length)]).join('')}
function qaPick(a){return a[Math.floor(Math.random()*a.length)]}
function qaFmtCpf(v){return v.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4')}
function qaFmtCnpj(v){return v.replace(/(.{2})(.{3})(.{3})(.{4})(.{2})/,'$1.$2.$3/$4-$5')}
const QA_LOC={pt:{country:'Brasil',first:['Marina','Lucas','Ana','Rafael','Camila','Bruno','Sofia','Diego'],last:['Almeida','Silva','Oliveira','Costa','Martins','Souza'],cities:[['São Paulo','SP','01310-000'],['Campinas','SP','13010-000'],['Rio de Janeiro','RJ','20040-000'],['Curitiba','PR','80010-000'],['Belo Horizonte','MG','30110-000']],streets:['Rua Exemplo','Avenida Teste','Rua das Flores','Avenida Central'],phones:['11','19','21','31','41']},en:{country:'United States',first:['Olivia','Liam','Emma','Noah','Sophia','James','Ava','Lucas'],last:['Miller','Johnson','Brown','Davis','Wilson','Taylor'],cities:[['New York','NY','10001'],['Los Angeles','CA','90001'],['Chicago','IL','60601'],['Austin','TX','78701'],['Seattle','WA','98101']],streets:['Test Street','Example Avenue','Quality Lane','Automation Road'],areas:['212','213','312','512','206']},es:{country:'España',first:['María','Lucía','Sofía','Daniel','Pablo','Laura','Carlos','Elena'],last:['García','Martínez','López','Sánchez','Pérez','Gómez'],cities:[['Madrid','Madrid','28001'],['Barcelona','Barcelona','08001'],['Valencia','Valencia','46001'],['Sevilla','Sevilla','41001'],['Bilbao','Bizkaia','48001']],streets:['Calle Ejemplo','Avenida de Prueba','Calle Mayor','Paseo Central']}};
function qaPerson(){let l=QA_LOC[LANG];return qaPick(l.first)+' '+qaPick(l.last)}
function qaUsSsn(){return `${String(100+Math.floor(Math.random()*800)).padStart(3,'0')}-${String(10+Math.floor(Math.random()*80)).padStart(2,'0')}-${String(1000+Math.floor(Math.random()*8000)).padStart(4,'0')}`}
function qaEsDni(){let n=String(Math.floor(Math.random()*99999999)).padStart(8,'0'),letters='TRWAGMYFPDXBNJZSQVHLCKE';return n+letters[Number(n)%23]}
function qaEsNie(){let p=qaPick(['X','Y','Z']),n=String(Math.floor(Math.random()*9999999)).padStart(7,'0'),letters='TRWAGMYFPDXBNJZSQVHLCKE',v=Number(({X:'0',Y:'1',Z:'2'})[p]+n);return p+n+letters[v%23]}
function qaPhone(valid=true){if(!valid)return LANG==='pt'?'+55 11 ABC':LANG==='en'?'+1 (000) 12':' +34 ABC';if(LANG==='pt'){let d=qaPick(QA_LOC.pt.phones);return `+55 (${d}) 9${qaRndDigits(4)}-${qaRndDigits(4)}`}if(LANG==='en'){let a=qaPick(QA_LOC.en.areas);return `+1 (${a}) 555-${String(100+Math.floor(Math.random()*100)).padStart(4,'0')}`}return `+34 ${qaPick(['6','7'])}${qaRndDigits(2)} ${qaRndDigits(3)} ${qaRndDigits(3)}`}
function qaAddress(valid=true){let l=QA_LOC[LANG],c=qaPick(l.cities);if(!valid)return LANG==='pt'?'Endereço/CEP propositalmente inválido':LANG==='en'?'Intentionally invalid address/ZIP Code':'Dirección/código postal intencionalmente inválido';let n=10+Math.floor(Math.random()*980);if(LANG==='pt')return `${qaPick(l.streets)}, ${n} - Bairro Exemplo - ${c[0]}/${c[1]} - CEP ${c[2]} - Brasil`;if(LANG==='en')return `${n} ${qaPick(l.streets)}, ${c[0]}, ${c[1]} ${c[2]}, United States`;return `${qaPick(l.streets)}, ${n} - ${c[0]}, ${c[1]} - Código Postal ${c[2]} - España`}
function qaTestCard(){let cards=[['Visa','4242 4242 4242 4242','123'],['Mastercard','5555 5555 5555 4444','123'],['American Express','3782 822463 10005','1234']],c=qaPick(cards),name=qaPerson(),y=new Date().getFullYear()+3,m=String(1+Math.floor(Math.random()*12)).padStart(2,'0');return `${name} | ${c[0]} | ${c[1]} | ${m}/${String(y).slice(-2)} | CVV/CVC ${c[2]} | TEST/SANDBOX`}
function qaTestDataOne(type,mode){let valid=mode!=='invalid';if(type==='person')return valid?qaPerson():'';if(type==='email'){let n=qaPerson().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll(' ','.');return valid?n+'@example.com':n+'example.com'}if(type==='phone')return qaPhone(valid);if(type==='address')return qaAddress(valid);if(type==='password')return valid?'Qa!'+qaRndAlphaNum(10):'123';if(type==='date'){let y=1980+Math.floor(Math.random()*30),m=1+Math.floor(Math.random()*12),d=1+Math.floor(Math.random()*28);return LANG==='en'?`${String(m).padStart(2,'0')}/${String(d).padStart(2,'0')}/${y}`:`${String(d).padStart(2,'0')}/${String(m).padStart(2,'0')}/${y}`}if(type==='number')return mode==='boundary'?'0 | 1 | 99 | 100 | 101':String(Math.floor(Math.random()*10000));if(type==='string')return mode==='boundary'?'"" | A | '+('X'.repeat(50))+' | '+('X'.repeat(51)):'QA-LAB-'+qaRndAlphaNum(8);if(type==='card')return qaTestCard();if(LANG==='pt'){if(type==='cpf'){let x=qaCpfDigits(qaRndDigits(9));if(!valid)x=x.slice(0,10)+((+x[10]+1)%10);return qaFmtCpf(x)}if(type==='cnpj'||type==='cnpj-alpha'){let base=type==='cnpj'?qaRndDigits(12):qaRndAlphaNum(12),x=qaCnpjDv(base);if(!valid)x=x.slice(0,13)+(x[13]==='9'?'0':'9');return qaFmtCnpj(x)}}if(LANG==='en'){if(type==='ssn')return valid?qaUsSsn():'000-00-0000';if(type==='itin')return valid?`9${qaRndDigits(2)}-${qaPick(['70','71','72','73','74','75','76','77','78','79','80','81','82','83','84','85','86','87','88'])}-${qaRndDigits(4)}`:'123-45-6789';if(type==='ein')return valid?`${qaPick(['10','12','20','27','30','35','80','81','82','83','84','85','86','87','88'])}-${qaRndDigits(7)}`:'00-0000000'}if(LANG==='es'){if(type==='dni')return valid?qaEsDni():qaRndDigits(8)+'A';if(type==='nie')return valid?qaEsNie():'A'+qaRndDigits(7)+'0'}return qaRndAlphaNum(12)}
function qaGenerateTestData(){let type=document.getElementById('tdType').value,mode=document.getElementById('tdMode').value,q=Math.min(50,Math.max(1,+document.getElementById('tdQty').value||1)),rows=Array.from({length:q},()=>qaTestDataOne(type,mode));window._qaTD=rows;document.getElementById('tdOutput').textContent=rows.join('\n')}
function qaCopyTestData(){navigator.clipboard?.writeText((window._qaTD||[]).join('\n'))}
function qaDownloadTestData(kind){let rows=window._qaTD||[];if(!rows.length)return;let body=kind==='json'?JSON.stringify(rows,null,2):'value\n'+rows.map(x=>'"'+String(x).replaceAll('"','""')+'"').join('\n');let b=new Blob([body],{type:kind==='json'?'application/json':'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='qa-test-data.'+(kind==='json'?'json':'csv');a.click();URL.revokeObjectURL(a.href)}
function qaDataOptions(){let common={pt:[['person','👤 Pessoa'],['cpf','🪪 CPF'],['cnpj','🏢 CNPJ numérico'],['cnpj-alpha','🏢 CNPJ alfanumérico'],['email','📧 E-mail'],['phone','📱 Telefone'],['address','🏠 Endereço + CEP'],['card','💳 Cartão de teste'],['password','🔐 Senha'],['date','📅 Data'],['number','🔢 Número'],['string','📝 String']],en:[['person','👤 Person'],['ssn','🪪 SSN'],['itin','🪪 ITIN'],['ein','🏢 EIN'],['email','📧 Email'],['phone','📱 Phone'],['address','🏠 Address + ZIP Code'],['card','💳 Test card'],['password','🔐 Password'],['date','📅 Date'],['number','🔢 Number'],['string','📝 String']],es:[['person','👤 Persona'],['dni','🪪 DNI / NIF'],['nie','🪪 NIE'],['email','📧 Correo electrónico'],['phone','📱 Teléfono'],['address','🏠 Dirección + Código Postal'],['card','💳 Tarjeta de prueba'],['password','🔐 Contraseña'],['date','📅 Fecha'],['number','🔢 Número'],['string','📝 String']]};return common[LANG]}
function renderTestDataGenerator(){let x={pt:{t:'Gerador de Massa de Testes',s:'Dados sintéticos para cenários positivos, negativos e valores-limite - sem consultar pessoas reais.',type:'Tipo de dado',mode:'Modo',qty:'Quantidade',gen:'Gerar massa',copy:'Copiar tudo',warn:'Dados exclusivamente para testes. Identificadores são sintéticos; cartões usam números documentados para sandbox e não devem ser usados em produção.',m:['Válido','Inválido','Limites']},en:{t:'QA Test Data Generator',s:'Synthetic data for positive, negative and boundary scenarios - without querying real people.',type:'Data type',mode:'Mode',qty:'Quantity',gen:'Generate',copy:'Copy all',warn:'Testing data only. Identifiers are synthetic; cards use documented sandbox numbers and must not be used in production.',m:['Valid','Invalid','Boundary']},es:{t:'Generador de Datos de Prueba',s:'Datos sintéticos para escenarios positivos, negativos y límites - sin consultar personas reales.',type:'Tipo de dato',mode:'Modo',qty:'Cantidad',gen:'Generar',copy:'Copiar todo',warn:'Datos solo para pruebas. Los identificadores son sintéticos; las tarjetas usan números documentados para sandbox y no deben usarse en producción.',m:['Válido','Inválido','Límites']}}[LANG],opts=qaDataOptions().map(([v,l])=>`<option value="${v}">${l}</option>`).join('');document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${x.t}</div><div class="ico">🧪</div><h1>${x.t}</h1><p>${x.s}</p></div><section class="topic-section test-data-tool"><div class="td-controls"><label>${x.type}<select id="tdType">${opts}</select></label><label>${x.mode}<select id="tdMode"><option value="valid">✅ ${x.m[0]}</option><option value="invalid">❌ ${x.m[1]}</option><option value="boundary">⚠️ ${x.m[2]}</option></select></label><label>${x.qty}<input id="tdQty" type="number" min="1" max="50" value="5"></label><button class="btn primary" onclick="qaGenerateTestData()">🧪 ${x.gen}</button></div><div class="tip">⚠️ ${x.warn}</div><pre id="tdOutput" class="td-output"></pre><div class="actions"><button class="btn" onclick="qaCopyTestData()">📋 ${x.copy}</button><button class="btn" onclick="qaDownloadTestData('json')">{ } JSON</button><button class="btn" onclick="qaDownloadTestData('csv')">📊 CSV</button></div></section>`;qaGenerateTestData();window.scrollTo(0,0)}

'''
